#include "mainwindow.h"
#include <QFileDialog>
#include <QDir>
#include <QDirIterator>
#include <QMessageBox>
#include <QAxObject>
#include <QFileInfo>

MainWindow::MainWindow(QWidget *parent) : QWidget(parent) {
    selectButton = new QPushButton("Select Folder", this);
    connect(selectButton, &QPushButton::clicked, this, &MainWindow::selectDirectory);
}

MainWindow::~MainWindow() {}

void MainWindow::selectDirectory() {
    QString dir = QFileDialog::getExistingDirectory(this, "Select Directory");
    if (!dir.isEmpty()) {
        processDirectory(dir);
    }
}

void MainWindow::processDirectory(const QString &dirPath) {
    QDir csvDir(dirPath);
    QString csvFolderPath = dirPath + "/Converted_CSVs";
    if (!csvDir.mkpath(csvFolderPath) && !QDir(csvFolderPath).exists()) {
        QMessageBox::critical(this, "Error", "Could not create CSV directory.");
        return;
    }

    QDirIterator fileIt(dirPath, {"*.xls", "*.xlsx"}, QDir::Files, QDirIterator::Subdirectories);
    int fileCount = 0;

    while (fileIt.hasNext()) {
        QString filePath = fileIt.next();
        ++fileCount;
        QFileInfo info(filePath);
        QString baseName = info.baseName();
        QString csvFilePath = QString("%1/%2.csv").arg(csvFolderPath).arg(baseName);

        // COM Automation
        QAxObject excel("Excel.Application");
        if (!excel.isNull()) {
            excel.setProperty("Visible", false);
            excel.setProperty("DisplayAlerts", false);

            QAxObject *workbooks = excel.querySubObject("Workbooks");
            QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", filePath);

            if (!workbook) {
                QMessageBox::warning(this, "Error", "Could not open workbook: " + filePath);
                continue;
            }

            QAxObject *sheet = workbook->querySubObject("Worksheets(int)", 1); // First sheet
            if (!sheet) {
                QMessageBox::warning(this, "Error", "Could not read worksheet from " + filePath);
                workbook->dynamicCall("Close()");
                continue;
            }
            sheet->dynamicCall("Activate()");
            bool ok = workbook->dynamicCall("SaveAs(const QString&, int)", csvFilePath, 6).toBool(); // 6 = CSV Format

            if (!ok) {
                QMessageBox::warning(this, "Error", "Failed to save as CSV: " + filePath);
            }

            workbook->dynamicCall("Close()");
        } else {
            QMessageBox::critical(this, "Error", "Excel not available. COM failed.");
            return;
        }
    }

    QString message = QString("Converted %1 Excel file(s) to CSV format.").arg(fileCount);
    QMessageBox::information(this, "Success", message);
}
